def article(item):
    slug, title, focus, thesis, fields, boundary = item
    sections = [
        (f'{title.split(":")[0]}: What {focus} solves', f'{thesis} In daily article creation for virtual assistant services, that distinction keeps a useful support routine from becoming a substitute for editorial judgment. Begin with the reader situation and the decision the article should support. A manager considering assistance, an operator coordinating a handoff, and an editor checking a public claim may all touch the same record, but they do not need the same answer. Name the audience before naming the task. Explain the boundary in plain language, identify the smallest useful next step, and state what evidence would change the recommendation. This prevents a workflow note from becoming an unsupported promise about a provider or outcome.'),
        (f'Build a {focus} record', f'Use observable fields rather than optimistic labels. Capture {fields}. Record unknowns as questions, not as plausible filler. The record should tell a person who was absent from the original request what is known, what is not known, and which decision is waiting. Keep the article route, current version, and related service context beside the item so a reviewer can see how it fits the site without inventing company facts.'),
        ('Walk through a virtual assistant services scenario', f'Consider a realistic scenario in which a virtual assistant is helping keep a daily article queue organized while an editor remains accountable for the public answer. Start with one concrete question, follow the record through research and review, and stop at every unresolved decision. Ask whether the next person can identify the evidence needed, the owner who must answer, and the consequence of proceeding too soon. If the scenario exposes a missing field, add the field or narrow the scope instead of hiding the gap inside more prose.'),
        ('Keep preparation separate from authority', f'{boundary} Make that boundary visible in the handoff itself. Organizing sources, comparing versions, checking a route, preparing an agenda, or flagging a contradiction can reduce friction. None of those actions automatically authorizes a public claim, a sensitive exception, a testimonial, a result, or a release decision. When uncertainty remains, preserve the uncertainty and route a precise question to the accountable owner.'),
        ('Measure decision usefulness', f'Use a defined sample to ask whether the record helped a real decision. Possible observations include complete-field coverage, time waiting for a named owner, number of reopened checks, correction reasons, and whether a reviewer could find the relevant evidence without reconstructing the whole request. Label the sample and period. A local measure describes the selected workflow under stated conditions; it does not prove a universal result or certify a provider.'),
        ('Design recovery into the handoff', f'Include the current version, completed checks, open questions, source links, proposed next action, and the condition that would send the work backward. Use precise statuses such as waiting for source review, returned for scope clarification, ready for editorial judgment, or approved for release. If the brief changes, record the changed question and reopen affected checks. Silent carryover is how an old assumption becomes a new public error.'),
        ('Review public boundaries before release', f'Check for invented company facts, unsupported specificity, private information, results presented as proof, testimonials, pricing or rate claims, and language that sounds more certain than the evidence permits. Label hypothetical examples. Keep recommendations conditional where context matters. A workflow control can make review more visible and repeatable, but it cannot guarantee that every article is correct. The editor or service owner remains accountable for the public answer.'),
        ('Close with a reopening trigger', f'Finish with a named owner and a concrete trigger such as a source change, reader question, broken destination, changed brief, unresolved approval condition, or recurring correction. That trigger turns {focus} into a maintainable routine for daily article creation. Virtual assistant services can keep evidence organized, route uncertainty, and protect continuity while writers and editors retain the decisions that shape what readers see.'),
    ]
    out = ['---', f'slug: {slug}', f'title: {title}', f'excerpt: Practical guidance for {focus} in virtual assistant services article operations.', f'publishedAt: {DATE}', f'updatedAt: {DATE}', 'category: Operations', 'tags: [virtual assistant, article creation, editorial operations]', 'featuredImage: /blog/images/virtual-assistant-content-brief-quality.webp', f'heroImageAlt: {title}', 'readingTime: 10 minutes', 'relatedArticles: [virtual-assistant-content-calendar-operations, virtual-assistant-provider-vetting-checklist, virtual-assistant-outsourcing-readiness-checklist]', '---', f'# {title}', '', f'{thesis} This guide keeps virtual assistant services central while preserving editorial accountability.']
    for heading, body in sections:
        out += ['', f'## {heading}', '', body]
    out += ['', '## Questions to ask before release', '', f'Can a reviewer identify the reader, evidence boundary, current owner, and next decision for this {focus} record? If not, pause the handoff and clarify it. Use the [services library](/services) for adjacent support lanes and the [provider vetting guide](/provider-vetting) when defining supervision and backup questions. For an access baseline, consult the [NIST small business cybersecurity guidance](https://www.nist.gov/itl/smallbusinesscyber).', '', '### What if the request changes?', '', 'Record the changed question and reopen affected checks. Do not silently carry an old thesis, source boundary, or approval into a materially different article.', '', '### Who makes the final decision?', '', 'The accountable editor or service owner decides public wording and release. A virtual assistant prepares evidence, maintains the record, and escalates uncertainty within the agreed role boundary.']
    return '\n'.join(out) + '\n'

for path in BLOG.glob('virtual-assistant-aug18-*.mdx'):
    path.unlink()
entries = []
for item in TOPICS:
    slug = item[0]
    path = BLOG / f'{slug}.mdx'
    path.write_text(article(item), encoding='utf-8')
    entries.append({'slug': slug, 'route': f'/blog/{slug}', 'sourcePath': f'content/blog/{slug}.mdx', 'sourceDateField': 'publishedAt', 'sourceDate': DATE, 'renderedDate': DATE, 'renderedDateFields': ['datePublished', 'time[datetime]'], 'provenance': 'fresh-aug18-identity-repair', 'introducedByCommit': 'PENDING'})
manifest = ROOT / '.paperclip/aug18-2026/blog.json'
manifest.write_text(json.dumps({'schemaVersion': 1, 'contract': 'fleet-aug18-blog-fresh-identity-v1', 'family': 'blog', 'targetDate': DATE, 'minimum': 22, 'entries': entries}, indent=2) + '\n', encoding='utf-8')
print(f'created {len(entries)} fresh articles; shortest body {min(len((BLOG / (e["slug"] + ".mdx")).read_text().split()) for e in entries)} words')
